<?php /** @var array $groupPage @var array $groups */
$h=static fn($value)=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$isCorp=$groupPage['catalogue'];$scope=$isCorp?'corporazioni':'organizzazioni';
$territories=array_values(array_unique(array_filter(array_column($groups,'city'))));sort($territories);
?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($groupPage['title'])?></title><script src="/js/groups.js" defer></script><script src="/js/registry.js" defer></script></head><body>
<?php if($groupPage['message']): ?><p class="flash" role="status"><?=$h($groupPage['message'])?></p><?php endif; ?>
<header class="ui-page-heading" data-page-heading><span data-icon="<?=$isCorp?'shield':'users'?>" aria-hidden="true"></span><div><div class="ui-eyebrow">Alphano · <?=$h($groupPage['title'])?></div><h1><?=$h($groupPage['title'])?></h1><p><?=$isCorp?'Mestieri, botteghe e conoscenze tramandate nelle mondo di gioco.':'Alleanze, ideali e appartenenze nelle mondo di gioco.'?></p></div><div class="registry-totals"><span><strong><?=count($groups)?></strong> <?=$h(count($groups)===1?$groupPage['singular']:$groupPage['title'])?></span><span><strong><?=count($territories)?></strong> <?=count($territories)===1?'Territorio':'Territori'?></span></div></header>
<main class="registry" data-registry data-registry-kind="groups" aria-label="<?=$h($groupPage['title'])?>">
 <div class="registry-toolbar"><div class="registry-filters" role="group" aria-label="Filtra per territorio"><button type="button" data-ui-no-icon data-registry-filter="all" aria-pressed="true">Tutte</button><?php foreach($territories as $territory): ?><button type="button" data-ui-no-icon data-registry-filter="<?=$h($territory)?>" aria-pressed="false"><?=$h($territory)?></button><?php endforeach; ?></div><label class="registry-search"><span data-icon="search" aria-hidden="true"></span><input type="search" data-registry-search aria-label="Cerca per nome, città o responsabile" placeholder="Cerca nome, città o responsabile…" autocomplete="off"></label></div>
 <p class="registry-count" data-registry-count role="status"><?=count($groups)?> elementi nel registro</p>
 <div class="registry-groups">
 <?php foreach($groups as $index=>$g): $gid=(int)$g['id'];$hierarchy='/'.$scope.'/gerarchia.php?'.$groupPage['parameter'].'='.$gid; ?>
 <article class="registry-group" data-registry-item data-territory="<?=$h($g['city'])?>" data-search="<?=$h($g['nome'].' '.$g['city'].' '.implode(' ',array_column($g['people'],'name')))?>" aria-label="<?=$h($g['nome'])?>">
  <div class="registry-group-top"><a class="registry-standard" href="<?=$hierarchy?>" aria-label="Cariche e partecipanti di <?=$h($g['nome'])?>"><?php if($g['stendardo']): ?><img src="<?=$h($g['stendardo'])?>" alt="Stendardo di <?=$h($g['nome'])?>" loading="lazy"><?php else: ?><span data-icon="<?=$isCorp?'shield':'users'?>" aria-hidden="true"></span><?php endif; ?></a>
   <div class="registry-group-title"><div class="ui-eyebrow"><?=$h($groupPage['singular'])?> · <?=str_pad((string)($index+1),2,'0',STR_PAD_LEFT)?></div><div class="registry-title-line"><h2><a href="<?=$hierarchy?>"><?=$h($g['nome'])?></a></h2>
    <?php if(!$groupPage['member']&&!$groupPage['pending']): ?><form method="post" data-group-join="<?=$h($g['nome'])?>"><input type="hidden" name="<?=$groupPage['parameter']?>" value="<?=$gid?>"><button class="registry-action registry-action-join" type="submit" data-icon="users">Richiedi ingresso</button></form><?php elseif($groupPage['member']===$gid): ?><span class="registry-membership">La tua <?=$h(strtolower($groupPage['singular']))?></span><?php elseif($groupPage['pending']): ?><button class="registry-action registry-action-join" type="button" disabled title="Attendi l’esito della richiesta già inviata">Richiesta in attesa</button><?php else: ?><button class="registry-action registry-action-join" type="button" disabled title="Devi prima uscire dalla tua attuale affiliazione">Richiedi ingresso</button><?php endif; ?>
   </div><div class="registry-place"><?php if($g['city_icon']): ?><img src="<?=$h($g['city_icon'])?>" width="28" height="28" alt=""><?php endif; ?><a href="/citta/?id=<?=$g['city_id']?>&amp;sezione=araldiche"><?=$h($g['city']?:'Sede non dichiarata')?></a></div></div>
  </div>
  <div class="registry-group-bottom"><section class="registry-responsibles" aria-label="Responsabili"><h3>Responsabili</h3><div class="group-responsibles"><?php foreach($g['people'] as $person): ?><a class="group-responsible" href="/profili/?Id=<?=$person['id']?>"><span class="group-person-media"><img src="<?=$h($person['avatar'])?>" data-default-src="<?=$h($person['default_avatar']??'/assets/placeholder.svg')?>" data-privacy-compact alt="" width="50" height="50" loading="lazy"></span><span><strong><?=$h($person['name'])?></strong><small><?=$h(implode(' · ',$person['roles']))?></small></span></a><?php endforeach; ?><?php if(!$g['people']): ?><p>Nessun responsabile nominato.</p><?php endif; ?></div></section>
  <nav class="registry-quick" aria-label="Accesso rapido a <?=$h($g['nome'])?>"><h3>Accesso rapido</h3><div class="registry-actions">
   <a class="registry-action registry-action-statute" data-icon="book" href="/<?=$scope?>/showstatuto.php?<?=$groupPage['parameter']?>=<?=$gid?>#statuto">Statuto</a>
   <?php if($isCorp): ?><a class="registry-action registry-action-catalogue" data-icon="coins" href="/corporazioni/catalogo.php?corp=<?=$gid?>">Catalogo</a><?php else: ?><a class="registry-action registry-action-members" data-icon="users" href="/ricerca/?organizzazione=<?=$gid?>">Membri</a><?php endif; ?>
   <?php if(alphano_can('admin')): ?><a class="registry-action registry-action-manage" data-icon="settings" href="/<?=$scope?>/admin.php?<?=$groupPage['parameter']?>=<?=$gid?>">Gestisci</a><?php if($isCorp): ?><a class="registry-action registry-action-trade" data-icon="scroll" href="/corporazioni/trasferimenti.php?corp=<?=$gid?>">Commercio</a><?php endif; ?><a class="registry-action registry-action-art" data-icon="shield" href="/gruppi/identita.php?scope=<?=$scope?>&amp;id=<?=$gid?>">Identità grafica</a><?php endif; ?>
   <?php if(!empty($g['sito'])): ?><a class="registry-action registry-action-external" data-icon="compass" href="<?=$h($g['sito'])?>" target="_blank" rel="noopener">Sito</a><?php endif; ?>
  </div></nav></div>
 </article><?php endforeach; ?></div>
 <p class="ui-empty" data-registry-empty hidden>Nessun risultato. Prova un altro nome o territorio.</p>
 <footer class="ui-list-footer"><?php if(!$groupPage['member']): ?><a class="action-btn" data-icon="users" href="<?=$h($groupPage['proposal'])?>">Proponi una <?=$h(strtolower($groupPage['singular']))?></a><?php else: ?><p>Per proporre una nuova <?=$h(strtolower($groupPage['singular']))?> devi prima uscire dalla tua attuale.</p><?php endif; ?></footer>
</main></body></html>
